class Solution {
public:
    int fixedPoint(vector<int>& arr) {
        int left = 0;
        int right = arr.size();
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] < mid) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left < static_cast<int>(arr.size()) && arr[left] == left
             ? left : -1;
    }
};
